  function beginFinish(){const f=fishing.fish,rush=timeAttack.running&&timeAttack.turnActive,tension=Math.max(0,Math.min(1,((f?.score||100)-100)/1950)),gradeWidth=f?.grade==='MYTHIC'?.13:f?.grade==='LEGEND'?.16:f?.grade==='SS'?.19:f?.grade==='S'?.22:f?.grade==='A'?.26:f?.grade==='B'?.31:.36,widthRoll=.86+Math.random()*.14,speedRoll=.94+Math.random()*.32,readyDelay=rush?500:850;mode='aim';fishing.aimLockUntil=now+readyDelay;fishing.aimStart=fishing.aimLockUntil;fishing.aimValue=0;fishing.aimTarget=.20+Math.random()*.60;fishing.aimWidth=Math.max(.12,Math.min(.42,(gradeWidth+selectedRod.power*.009+(rush?.025:0))*widthRoll));fishing.aimSpeed=Math.max(.0031,Math.min(rush?.0078:.0088,(f?.aimSpeed??.0019)*(1.9+tension*.68)*speedRoll+(rush?.0004:0)));fishing.deadline=fishing.aimStart+(rush?5600:Math.max(5200,(f?.aimTime??12500)*.68));el.meter.classList.remove('hidden');el.meter.classList.add('aim');el.aimCursor.style.left='0%';el.aimTarget.style.left=`${(fishing.aimTarget-fishing.aimWidth/2)*100}%`;el.aimTarget.style.width=`${fishing.aimWidth*100}%`;el.action.className='action-button bite locked';el.action.textContent=ui('타이밍 준비…','Get ready…');el.meterText.textContent=ui('정체 불명 · 움직이는 바늘을 노란 칸에서 멈추세요','Unknown catch · stop the moving marker in the yellow zone');el.bar.innerHTML=ui('릴 감기 성공! <b>하얀 막대가 노란 칸에 들어올 때</b> 한 번만 눌러 멈추세요. 빗나가면 놓쳐요!','Reeling complete! <b>Press once while the white marker is in the yellow zone.</b> Miss it and the catch escapes!');setNotice(ui(`집중! ${rush?'0.5':'0.8'}초 뒤 바늘이 출발해요.`,`Focus! The marker starts in ${rush?'0.5':'0.8'} seconds.`));setTimeout(()=>{if(mode==='aim'&&now>=fishing.aimLockUntil){el.action.classList.remove('locked');el.action.textContent=ui('지금 멈추기!','STOP NOW!')}},rush?540:880)}
