  function fishLearningInfo(f){const size=f.scale>=2.5?'초거대':f.scale>=1.6?'아주 큰':f.scale>=1.2?'큰':'작은',length=Math.round((f.real?22:32)+(f.scale||1)*48+(f.gridIndex===undefined?0:(f.gridIndex%5)*5)),trait=fishSubtitle(f);if(language==='en')return `<b>Size:</b> ${size==='초거대'?'Colossal':size==='아주 큰'?'Very large':size==='큰'?'Large':'Small'} · about ${length} cm in this game<br><b>Learn:</b> ${trait}. Look at its body shape and fins to imagine how it swims.`;return `<b>크기:</b> 게임 속 약 ${length}cm · ${size} 친구<br><b>특징:</b> ${trait}. 몸 모양과 지느러미를 보고 어떻게 헤엄칠지 생각해 보세요!`}
