  function buildCollectionCards(){const seen=new Set(caught.map(entry=>entry.id));el.collectionCards.replaceChildren();el.collectionHint.textContent=ui(`전체 ${fish.length}종 · ${seen.size}종 발견 · 카드를 눌러 크게 보세요`,`${fish.length} species · ${seen.size} discovered · Tap a card to see it big`);fish.forEach(f=>{const card=document.createElement('button'),cv=document.createElement('canvas'),copy=document.createElement('div'),tag=document.createElement('small'),legendRod=legendRodFor(f),count=caught.filter(entry=>entry.id===f.id).length;card.type='button';card.className=`collection-card${seen.has(f.id)?' caught':''}${legendRod?' rod-legend':''}`;card.setAttribute('aria-label',ui(`${fishName(f)} 자세히 보기`,`View ${fishName(f)} details`));cv.width=220;cv.height=140;drawResultFish(cv.getContext('2d'),f);tag.textContent=legendRod?ui(`전용: ${rodName(legendRod)}`,`Signature: ${rodName(legendRod)}`):gradeLabel(f.grade);copy.innerHTML=`<b>${fishName(f)}</b><small>${fishSubtitle(f)}</small><p>${seen.has(f.id)?ui(`${count}마리 수족관에 있어요`,`${count} in your aquarium`):ui('아직 못 만났어요','Not found yet')}</p>`;copy.prepend(tag);card.append(cv,copy);card.onclick=()=>openFishDetail(f,count);el.collectionCards.append(card)})}
