  function fishSaleValue(f){return Math.max(20,Math.round((f.score||100)*.25/5)*5)}
  function buildSellChoices(){el.sellChoices.replaceChildren();if(!caught.length){el.sellHint.textContent='아직 판매할 물고기가 없어요. 항구에서 낚은 물고기는 여기서 코인으로 바꿀 수 있어요.';const empty=document.createElement('div');empty.className='sell-empty';empty.textContent='수족관이 비어 있어요. 첫 물고기를 낚아 보세요!';el.sellChoices.append(empty);return}el.sellHint.textContent=`전시 중인 물고기 ${caught.length}마리 · 판매하면 코인으로 바뀌고 수족관에서 떠나요.`;caught.forEach((entry,index)=>{const f=fish.find(v=>v.id===entry.id);if(!f)return;const b=document.createElement('button'),cv=document.createElement('canvas'),copy=document.createElement('span'),value=document.createElement('strong');b.type='button';b.className='sell-choice';cv.width=116;cv.height=92;drawResultFish(cv.getContext('2d'),f);copy.innerHTML=`<b>${f.name}</b><small>${f.grade} · 수족관에서 판매</small>`;value.textContent=`+${fishSaleValue(f)} 코인`;b.append(cv,copy,value);b.onclick=()=>sellFish(index);el.sellChoices.append(b)})}
  function sellFish(index){if(mode!=='aquarium'||feeding){setNotice(feeding?'먹이를 먹는 동안에는 판매할 수 없어요.':'수족관에서만 판매할 수 있어요.');return}const entry=caught[index],f=fish.find(v=>v.id===entry?.id);if(!f)return;const value=fishSaleValue(f);caught.splice(index,1);coins+=value;save();updateHud();buildSellChoices();buildFeedTray();setNotice(`${f.name}을(를) 판매해 ${value}코인을 받았어요!`);audio('catch')}
  function openSellMarket(){if(mode!=='aquarium')return;buildSellChoices();el.sellOverlay.classList.remove('hidden')}
  function catchFish(){const f=fishing.fish;if(timeAttack.running&&timeAttack.turnActive){timeAttackCatch({fish:f});return}const stamp=Date.now(),legendary=['LEGEND','MYTHIC'].includes(f.grade);caught.push({id:f.id,seed:Math.floor(Math.random()*99999),caughtAt:stamp,fullness:100,fullnessAt:stamp,starvingAt:0,hungerAlertLevel:0});save();updateHud();mode='harbor';el.meter.classList.remove('aim');el.meter.classList.add('hidden');el.action.className='action-button hidden';resetResultActions();drawResultFish(el.resultCanvas.getContext('2d'),f);const panel=el.result.querySelector('.result-panel');panel.classList.toggle('legendary-result',legendary);el.resultEye.textContent=legendary?ui('✦ 전설 물고기 등장! ✦','✦ LEGENDARY CATCH! ✦'):language==='en'?'NEW SEA FRIEND':'새 바다 친구';el.resultTitle.textContent=language==='en'?`You caught ${fishName(f)}!`:`${fishName(f)}을 잡았다!`;el.resultCopy.innerHTML=`${fishLearningInfo(f)}<br><span>${legendary?ui('황금 별빛이 항구를 가득 채웠어요! 도감과 수족관에 특별하게 기록됩니다.','Golden starlight fills the harbor! This legend is marked specially in your Fish Book and aquarium.'):language==='en'?'You can catch the same fish again and meet it in the aquarium.':'같은 물고기도 계속 낚여 수족관 친구가 됩니다.'}</span>`;el.result.classList.remove('hidden');if(legendary){setNotice(ui('전설이다! 반짝이는 바다 친구를 잡았어요!','A legend! You caught a sparkling sea friend!'));audio('catch');setTimeout(()=>audio('catch'),110)}else setNotice(language==='en'?'Added to your Fish Book!':'수족관 도감에 기록했어요!');gamerClockComplete(f);audio('catch')}
  function catchLoot(){const item=fishing.item;if(timeAttack.running&&timeAttack.turnActive){timeAttackCatch({item});return}mode='harbor';el.meter.classList.remove('aim');el.meter.classList.add('hidden');el.action.className='action-button hidden';const rctx=el.resultCanvas.getContext('2d');rctx.clearRect(0,0,220,140);rctx.imageSmoothingEnabled=false;drawLoot(rctx,item,110,72,2.35);el.resultEye.textContent=item.kind==='feed'?ui('새 미끼 또는 먹이','NEW BAIT OR FEED'):ui('새 수족관 장식','NEW AQUARIUM DECOR');el.resultTitle.textContent=ui(`${itemName(item)}을 건졌다!`,`You found ${itemName(item)}!`);if(item.kind==='feed'){pendingLoot=item;$('#backHarbor').textContent=ui('먹이로 보관','Store as Food');$('#openAquarium').textContent=ui('미끼로 보관','Store as Bait');el.resultCopy.textContent=ui(`${baitTierName(item.bait)} 미끼예요. 수족관 먹이로 보관하거나, ${baitChanceLabel(item.bait)} 미끼로 챙길 수 있어요.`,`${baitTierName(item.bait)} bait. Store it as aquarium food, or keep it as bait: ${baitChanceLabel(item.bait)}.`)}else{resetResultActions();inventory.push({id:item.id,role:'deco',seed:Math.floor(Math.random()*99999),caughtAt:Date.now()});save();updateHud();el.resultCopy.textContent=ui('수족관 안에 새 장식으로 바로 배치했어요.','The new decor is ready in your aquarium.')}el.result.classList.remove('hidden');setNotice(item.kind==='feed'?ui('어떻게 보관할지 선택하세요.','Choose how to store it.'):ui('수족관 장식을 보관했어요!','Aquarium decor stored!'));audio('catch')}
  function boxEntries(){return inventory.map((entry,index)=>({entry,index,box:randomBoxes.find(box=>box.id===entry.id)})).filter(v=>v.box&&v.entry.role==='box')}
  function drawBoxResult(box,eyebrow,title,copy,destination='boxes'){const rctx=el.resultCanvas.getContext('2d');rctx.clearRect(0,0,220,140);rctx.imageSmoothingEnabled=false;drawBox(rctx,box,110,72,.72);resetResultActions();resultDestination=destination;el.resultEye.textContent=eyebrow;el.resultTitle.textContent=title;el.resultCopy.textContent=copy;$('#openAquarium').innerHTML=destination==='aquarium'?'수족관에 전시 <span>→</span>':'상자 보관함 열기 <span>→</span>';el.result.classList.remove('hidden')}
  function catchBox(){const box=fishing.box;if(!box)return;const stamp=Date.now();inventory.push({id:box.id,role:'box',seed:Math.floor(Math.random()*99999),caughtAt:stamp});save();updateHud();mode='harbor';el.meter.classList.remove('aim');el.meter.classList.add('hidden');el.action.className='action-button hidden';drawBoxResult(box,'RARE SURPRISE BOX',`${box.name}을 건졌다!`,`희귀한 ${box.grade} 랜덤 상자예요. 꽝·쓰레기·물고기 3마리·미끼 10개·장식 3개, 또는 전설 물고기 1마리가 들어 있어요.`);setNotice('랜덤 상자를 보관함에 넣었어요!');audio('catch')}
  function rollBoxOutcome(box){const total=Object.values(box.outcomes).reduce((sum,value)=>sum+value,0);let roll=Math.random()*total;return Object.keys(box.outcomes).find(key=>(roll-=box.outcomes[key])<=0)||'empty'}
  function randomBaitForBox(tier){const pool=aquariumItems.filter(item=>item.kind==='feed'&&item.bait<=tier);return pool[Math.floor(Math.random()*pool.length)]||aquariumItems[0]}
  function openBoxAt(index){const entry=inventory[index],box=randomBoxes.find(v=>v.id===entry?.id);if(!box)return;inventory.splice(index,1);const stamp=Date.now(),outcome=rollBoxOutcome(box);let title,copy,destination='boxes';if(outcome==='fish'){const prizes=Array.from({length:3},()=>chooseWeighted(box.tier));prizes.forEach(f=>caught.push({id:f.id,seed:Math.floor(Math.random()*99999),caughtAt:stamp,fullness:100,fullnessAt:stamp}));title='물고기 3마리 획득!';copy=prizes.map(f=>f.name).join(' · ');destination='aquarium'}else if(outcome==='legend'){const pool=fish.filter(f=>f.grade==='LEGEND'),prize=pool[Math.floor(Math.random()*pool.length)];caught.push({id:prize.id,seed:Math.floor(Math.random()*99999),caughtAt:stamp,fullness:100,fullnessAt:stamp});title='전설 물고기 1마리 획득!';copy=`${prize.name}이(가) 상자에서 나타났어요!`;destination='aquarium'}else if(outcome==='bait'){const prizes=Array.from({length:10},()=>randomBaitForBox(box.tier));prizes.forEach(item=>inventory.push({id:item.id,role:'bait',seed:Math.floor(Math.random()*99999),caughtAt:stamp}));title='미끼 10개 획득!';copy=`${baitTierName(box.tier)} 등급까지의 미끼 10개를 미끼 보관함에 넣었어요.`}else if(outcome==='decor'){const pool=aquariumItems.filter(item=>item.kind==='deco'),prizes=Array.from({length:3},()=>pool[Math.floor(Math.random()*pool.length)]);prizes.forEach(item=>inventory.push({id:item.id,role:'deco',seed:Math.floor(Math.random()*99999),caughtAt:stamp}));title='장식 3개 획득!';copy=prizes.map(item=>item.name).join(' · ')}else if(outcome==='trash'){title='쓰레기만 나왔어요…';copy='젖은 깡통과 해초 뭉치뿐이었어요. 다음 상자를 노려보세요.'}else{title='아쉽게도 꽝!';copy='상자가 텅 비어 있었어요. 희귀 상자는 언제나 좋은 것만 주지는 않아요.'}save();updateHud();buildBoxChoices();el.boxOverlay.classList.add('hidden');drawBoxResult(box,'SURPRISE BOX OPEN',title,copy,destination);if(outcome==='trash'){const rctx=el.resultCanvas.getContext('2d');rctx.clearRect(0,0,220,140);drawContained(rctx,images.trashReward,18,7,184,126)}setNotice(title);audio(['fish','legend','bait','decor'].includes(outcome)?'catch':'fail')}
  function buildBoxChoices(){const boxes=boxEntries();el.boxChoices.replaceChildren();if(!boxes.length){el.boxHint.textContent='아직 보관한 랜덤 상자가 없어요. 미끼를 사용해 낚시하면 아주 드물게 건질 수 있어요.';return}el.boxHint.textContent=`보관 중인 랜덤 상자 ${boxes.length}개. 개봉하면 결과가 바로 확정돼요.`;boxes.forEach(({index,box})=>{const b=document.createElement('button'),img=document.createElement('img'),copy=document.createElement('span'),small=document.createElement('small');b.type='button';b.className=`box-choice grade-${box.grade}`;img.src=box.src;img.alt='';copy.textContent=box.name;small.textContent=`${box.grade} · 열어 보기`;copy.append(small);b.append(img,copy);b.onclick=()=>openBoxAt(index);el.boxChoices.append(b)})}
  function openBoxPouch(){buildBoxChoices();el.boxOverlay.classList.remove('hidden')}
  function storePendingLoot(role){if(!pendingLoot)return false;const item=pendingLoot;inventory.push({id:item.id,role,seed:Math.floor(Math.random()*99999),caughtAt:Date.now()});save();updateHud();resetResultActions();el.result.classList.add('hidden');mode='harbor';setNotice(role==='bait'?`${item.name}을(를) 미끼 보관함에 넣었어요!`:`${item.name}을(를) 먹이 보관함에 넣었어요!`);return true}
  function fail(reason='time'){if(!['bite','reel','aim'].includes(mode))return;const rush=timeAttack.running&&timeAttack.turnActive;mode='failure';fishing.failureReason=reason;el.notice.classList.add('hidden');el.meter.classList.remove('aim');el.meter.classList.add('hidden');el.action.className='action-button hidden';el.bar.innerHTML=rush?ui('놓쳤어요! 다음 입질을 빠르게 노려보세요.','Escaped! Quickly try for the next bite.'):ui(reason==='range'?'<b>놓쳤어요!</b> 노란 칸 밖에서 멈췄어요. 물고기가 낚시꾼을 꿀꺽!':'<b>줄이 풀렸어요!</b> 시간이 지나 물고기가 낚시꾼을 꿀꺽!',reason==='range'?'<b>It escaped!</b> You stopped outside the yellow zone.':'<b>The line slipped!</b> Time ran out and the fish gulped the fisher.');setTimeout(()=>{mode='harbor';const p=scene.portrait?{x:500,y:960}:{x:610,y:425};player.x=p.x;player.y=p.y;player.targetX=p.x;player.targetY=p.y;if(rush&&timeAttack.running&&timeAttack.turnActive)castTimeAttackLine();else setNotice(ui('괜찮아요! 슬라이더 속도와 노란 칸을 보고 다시 도전해요.','Try again! Watch the slider speed and yellow zone.'))},rush?900:1750);audio('fail')}
  function buyTheme(theme){if(themeUnlocked(theme)){selectedTheme=theme;save();setNotice(ui(`${themeName(theme)} 전시관으로 바꿨어요!`,`Switched to the ${themeName(theme)} aquarium!`));return}if(coins<theme.price){setNotice(ui(`${theme.price-coins}코인이 더 필요해요. 물고기를 판매해 보세요!`, `You need ${theme.price-coins} more coins. Try selling a fish!`));return}coins-=theme.price;ownedThemes.push(theme.id);selectedTheme=theme;save();updateHud();setNotice(ui(`${themeName(theme)} 전시관을 구매했어요!`,`Bought the ${themeName(theme)} aquarium!`));audio('catch')}
  function baitShopPrice(item){return [0,24,38,64][item.bait]||24}
  function baitGlyph(item){return item.bait===3?'✨':item.bait===2?'🦐':'🪱'}
  function buyShopBait(item){const price=baitShopPrice(item);if(coins<price){setNotice(ui(`${price-coins}코인이 더 필요해요.`, `You need ${price-coins} more coins.`));return}coins-=price;inventory.push({id:item.id,role:'bait',seed:Math.floor(Math.random()*99999),caughtAt:Date.now()});save();updateHud();renderShop();setNotice(ui(`${itemName(item)} 미끼를 샀어요!`,`Bought ${itemName(item)} bait!`));audio('catch')}
  function cartTotal(){return shopCart.reduce((sum,entry)=>sum+entry.price,0)}
  function addToShopCart(kind,entry){const price=kind==='theme'?entry.price:baitShopPrice(entry);if(kind==='theme')shopCart=shopCart.filter(v=>v.kind!=='theme');shopCart.push({kind,id:entry.id,price});renderShop();const left=coins-cartTotal();setNotice(left>=0?ui(`담았어요! 결제하면 ${left}코인이 남아요.`,`Added! ${left} coins will remain after checkout.`):ui(`${Math.abs(left)}코인이 모자라요. 장바구니에서 빼거나 물고기를 팔아보세요!`,`You need ${Math.abs(left)} more coins. Remove an item or sell fish!`))}
  function renderShopCart(){const cart=$('#shopCart'),items=$('#shopCartItems'),count=$('#shopCartCount'),balance=$('#shopCartBalance'),total=cartTotal(),left=coins-total;count.textContent=shopCart.length;if(cart.classList.contains('hidden'))return;items.replaceChildren();if(!shopCart.length){const empty=document.createElement('p');empty.className='shop-cart-empty';empty.textContent=ui('아직 담은 물건이 없어요. 마음에 드는 물건을 눌러 담아보세요!','Your cart is empty. Tap an item you like to add it!');items.append(empty);balance.innerHTML=ui('<b>내 코인 0</b><span>물건을 담으면 결제 뒤 남는 코인을 알려드려요.</span>','<b>Your coins: 0</b><span>Add an item to see the coins left after checkout.</span>').replace('0',String(coins));$('#shopCheckout').disabled=true;return}const grouped=new Map();shopCart.forEach(entry=>{const key=`${entry.kind}:${entry.id}`,old=grouped.get(key)||{...entry,count:0};old.count++;grouped.set(key,old)});grouped.forEach(entry=>{const data=entry.kind==='theme'?aquariumThemes.find(v=>v.id===entry.id):aquariumItems.find(v=>v.id===entry.id),row=document.createElement('div'),remove=document.createElement('button');row.className='shop-cart-item';row.innerHTML=`<span>${entry.kind==='theme'?'🏛':'🪱'}</span><b>${entry.kind==='theme'?themeName(data):itemName(data)}${entry.count>1?` × ${entry.count}`:''}</b><strong>${entry.price*entry.count} ${ui('코인','coins')}</strong>`;remove.type='button';remove.textContent='×';remove.setAttribute('aria-label',ui('장바구니에서 빼기','Remove from cart'));remove.onclick=()=>{const i=shopCart.findIndex(v=>v.kind===entry.kind&&v.id===entry.id);if(i>=0)shopCart.splice(i,1);renderShop()};row.append(remove);items.append(row)});balance.className=`shop-cart-balance ${left>=0?'enough':'short'}`;balance.innerHTML=left>=0?ui(`<small>내 코인 <b>${coins}</b> → 장바구니 <b>${total}</b></small><strong>결제하면 <b>${left}</b>코인이 남아요!</strong>`,`<small>Your coins <b>${coins}</b> → Cart <b>${total}</b></small><strong><b>${left}</b> coins will be left after checkout!</strong>`):ui(`<small>내 코인 <b>${coins}</b> → 장바구니 <b>${total}</b></small><strong><b>${Math.abs(left)}</b>코인이 모자라요!</strong><span>물건을 빼거나 물고기를 팔아 코인을 모아보세요.</span>`,`<small>Your coins <b>${coins}</b> → Cart <b>${total}</b></small><strong>You need <b>${Math.abs(left)}</b> more coins!</strong><span>Remove an item or sell fish to earn more coins.</span>`);$('#shopCheckout').disabled=false;$('#shopCheckout').innerHTML=left>=0?ui('결제하기 <span>→</span>','Pay Now <span>→</span>'):ui('코인이 모자라요','Not Enough Coins')}
  function setSimpleShopCopy(){if(mode!=='shop')return;el.shopHint.textContent=shopTab==='themes'?ui('마음에 드는 전시관을 장바구니에 담아보세요. 결제 뒤 남는 코인을 바로 알려드려요!','Add a theme to your cart. We will show the coins left right away!'):ui('미끼를 장바구니에 담아보세요. 결제 뒤 남는 코인을 바로 알려드려요!','Add bait to your cart. We will show the coins left right away!');el.shopDialogueText.textContent=ui('마음에 드는 물건을 담아봐! 남는 코인은 내가 바로 알려줄게.','Add something you like! I will show the coins left right away.');$('#shopCartEyebrow').textContent=ui('내 코인 결제','YOUR COINS');$('#shopCartTitle').textContent=ui('내 장바구니','My Cart')}
  function openShopCart(){const cart=$('#shopCart'),shell=document.querySelector('.game-shell');if(cart.parentElement!==shell)shell.append(cart);cart.classList.remove('hidden');setSimpleShopCopy();$('#shopCheckout').innerHTML=ui('결제하기 <span>→</span>','Pay Now <span>→</span>');renderShopCart()}
  function checkoutShopCart(){const total=cartTotal(),left=coins-total;if(!shopCart.length){setNotice(ui('먼저 물건을 장바구니에 담아보세요.','Add an item to your cart first.'));return}if(left<0){setNotice(ui(`${Math.abs(left)}코인이 더 필요해요. 물건을 빼거나 물고기를 팔아보세요!`,`You need ${Math.abs(left)} more coins. Remove an item or sell fish!`));const balance=$('#shopCartBalance');balance.classList.remove('short');void balance.offsetWidth;balance.classList.add('short','shake');setTimeout(()=>balance.classList.remove('shake'),420);return}shopCart.forEach(entry=>{if(entry.kind==='theme'){const theme=aquariumThemes.find(v=>v.id===entry.id);if(theme&&!themeUnlocked(theme)){ownedThemes.push(theme.id);selectedTheme=theme}}else inventory.push({id:entry.id,role:'bait',seed:Math.floor(Math.random()*99999),caughtAt:Date.now()})});coins-=total;shopCart=[];save();updateHud();$('#shopCart').classList.add('hidden');renderShop();setNotice(ui(`결제 완료! ${left}코인이 남았어요.`,`Payment complete! ${left} coins left.`));audio('catch')}
  function renderShop(){el.shopCoinCount.textContent=coins;el.shopTabs.querySelectorAll('button').forEach(button=>button.classList.toggle('selected',button.dataset.shopTab===shopTab));el.shopChoices.replaceChildren();if(shopTab==='themes'){el.shopHint.textContent=ui('전시관을 누르면 장바구니에 담겨요. 결제 전에 남는 코인을 계산해요!','Tap a theme to add it to your cart. Work out the coins left before paying!');aquariumThemes.forEach(theme=>{const owned=themeUnlocked(theme),b=document.createElement('button'),img=document.createElement('img'),copy=document.createElement('span'),price=document.createElement('strong');b.type='button';b.className=`shop-choice${!owned&&coins<theme.price?' unaffordable':''}`;img.src=theme.src;img.alt='';copy.innerHTML=`<b>T${theme.tier} · ${themeName(theme)}</b><small>${owned?(theme.id===selectedTheme.id?ui('지금 사용 중','In use'):ui('내 전시관','Owned')):ui('장바구니에 담기','Add to cart')}</small>`;price.textContent=owned?ui('고르기','Select'):`${theme.price} ${ui('코인','coins')}`;b.append(img,copy,price);b.onclick=()=>{if(owned){selectedTheme=theme;save();setNotice(ui(`${themeName(theme)} 전시관으로 바꿨어요!`,`Switched to the ${themeName(theme)} aquarium!`));renderShop()}else addToShopCart('theme',theme)};el.shopChoices.append(b)})}else{el.shopHint.textContent=ui('미끼를 눌러 장바구니에 담고, 계산을 맞히면 결제돼요.','Tap bait to add it to your cart, then solve the math to pay.');aquariumItems.filter(item=>item.kind==='feed').forEach(item=>{const price=baitShopPrice(item),b=document.createElement('button'),icon=document.createElement('span'),copy=document.createElement('span'),cost=document.createElement('strong');b.type='button';b.className=`shop-choice${coins<price?' unaffordable':''}`;icon.className='bait-icon';icon.textContent=baitGlyph(item);copy.innerHTML=`<b>${itemName(item)}</b><small>${baitChanceLabel(item.bait)}</small>`;cost.textContent=`${price} ${ui('코인','coins')}`;b.append(icon,copy,cost);b.onclick=()=>addToShopCart('bait',item);el.shopChoices.append(b)})}renderShopCart();el.shopDialogueText.textContent=shopTab==='themes'?ui('장바구니에 담고 남은 코인을 계산해 봐!','Add it to the cart, then calculate your coins left!'):ui('좋은 미끼를 담고 계산까지 해 보자!','Pick good bait, then solve the checkout math!')}
  function openShop(){if(!['harbor','aquarium','shop','menu'].includes(mode)||timeAttack.running){setNotice(ui('낚시 도전 중에는 끝낸 뒤 상점에 갈 수 있어요.','Finish the current fishing challenge before visiting the shop.'));return}if(!el.result.classList.contains('hidden')){setNotice(ui('보상을 먼저 확인한 뒤 상점에 가요.','Check your reward before visiting the shop.'));return}const shopkeeper=el.shopDialogue.querySelector('img');if(!shopkeeper.getAttribute('src'))shopkeeper.src=shopkeeper.dataset.src;clearNavigationOverlays();mode='shop';shopTab='themes';feeding=null;el.notice.classList.add('hidden');el.feedTray.classList.add('hidden');el.sellButton.classList.add('hidden');el.shopWindow.classList.remove('hidden');el.shopDialogue.classList.remove('hidden');renderShop()}
  function leaveShop(){mode='harbor';$('#shopCart').classList.add('hidden');el.shopWindow.classList.add('hidden');el.shopDialogue.classList.add('hidden');setNotice(ui('상점 구경을 마쳤어요.','Finished browsing the shop.'))}
