  function skillTitle(type){return {memory:ui('구슬 기억하기','Bead Memory'),bubble:ui('거품 톡톡!','Bubble Pop'),current:ui('물살 읽기','Read the Current'),net:ui('그물 피하기','Safe Net'),count:ui('파도 세기','Count the Waves'),shell:ui('조개 찾기','Find the Shell'),sonar:ui('소나 신호','Sonar Signal'),knot:ui('매듭 세기','Count the Knots'),depth:ui('깊이 읽기','Read the Depth'),compass:ui('나침반 기억','Compass Memory'),tide:ui('조류 짝맞추기','Tide Match'),lantern:ui('등불 찾기','Find the Lantern'),star:ui('별빛 찾기','Find the Star'),lure:ui('미끼 짝맞추기','Lure Match'),scales:ui('무게 비교','Weight Match')}[type]||ui('바다 도전','Sea Challenge')}
  function skillInstruction(type){return {memory:ui('잠깐 보인 색 구슬 순서를 그대로 누르세요.','Remember the bead colors, then tap that order.'),bubble:ui('빛나는 거품을 여러 번 찾아 터뜨리세요!','Pop the glowing bubbles several times!'),current:ui('화살표와 같은 방향을 골라 물살을 따라가요.','Choose the matching arrow to follow the current.'),net:ui('물고기 쪽 그물만 골라 안전하게 끌어올려요.','Choose the fish net and avoid the rocky nets.'),count:ui('나란히 보이는 파도를 하나씩 세고 알맞은 숫자를 고르세요.','Count the separate waves one by one, then choose the number.'),shell:ui('위에 보인 조개와 똑같은 것을 고르세요.','Choose the shell shown above.'),sonar:ui('울린 소나 신호와 같은 칸을 누르세요.','Tap the lane with the matching sonar ping.'),knot:ui('밧줄 매듭 수를 세고 같은 숫자를 고르세요.','Count the rope knots, then choose that number.'),depth:ui('잠깐 보인 깊이 표시와 같은 숫자를 고르세요.','Match the depth marker you just saw.'),compass:ui('나침반 화살표 순서를 기억해서 다시 누르세요.','Remember the compass-arrow sequence.'),tide:ui('물살 모양과 같은 표식을 고르세요.','Match the current symbol.'),lantern:ui('빛나는 등불을 빠르게 찾으세요.','Find the glowing lantern quickly.'),star:ui('반짝이는 별빛을 여러 번 찾아 누르세요.','Tap the sparkling stars several times.'),lure:ui('물고기가 찾는 미끼와 같은 것을 고르세요.','Match the bait the fish is looking for.'),scales:ui('더 무거운 쪽의 물고기를 고르세요.','Choose the heavier side.' )}[type]||ui('알맞은 선택을 하세요.','Make the matching choice.')}
  function skillDifficulty(fish){const score=fish?.score||100;if(score>=1200)return{tier:'legend',goal:5,time:7600};if(score>=600)return{tier:'hard',goal:4,time:8800};if(score>=250)return{tier:'medium',goal:3,time:9900};return{tier:'easy',goal:2,time:10800}}
  function rollSkillRound(){
    const type=fishing.skill,previous=fishing.skillLastTarget;
    const target=(length)=>{let next=Math.floor(Math.random()*length);if(length>1&&next===previous)next=(next+1+Math.floor(Math.random()*(length-1)))%length;fishing.skillLastTarget=next;return next};
    if(type==='bubble'||type==='star')fishing.skillTarget=target(9);
    else if(type==='net')fishing.skillTarget=target(6);
    else if(['current','shell','tide','lantern','lure'].includes(type))fishing.skillTarget=target(4);
    else if(type==='sonar')fishing.skillTarget=target(3);
    else if(type==='knot'){fishing.skillCount=1+Math.floor(Math.random()*4);fishing.skillTarget=fishing.skillCount}
    else if(type==='depth'){fishing.skillTarget=Math.floor(Math.random()*4);fishing.skillCount=[10,20,30,40][fishing.skillTarget]}
    else if(type==='scales'){let left=1+Math.floor(Math.random()*4),right=1+Math.floor(Math.random()*4);if(left===right)right=right===4?1:right+1;fishing.skillLeft=left;fishing.skillRight=right;fishing.skillTarget=left>right?0:1}
  }
  function nextSkillRound(){
    const stamp=phaseTime();if(mode!=='skill'||stamp<(fishing.skillInputLockUntil||0))return;
    fishing.skillInputLockUntil=stamp+180;fishing.skillStep++;
    if(fishing.skillStep>=fishing.skillGoal)return completeSkill();
    rollSkillRound();renderSkill()
  }
