      stage.append(skillCue(`🐟 ${'●'.repeat(fishing.skillLeft)}  ⚖️  ${'●'.repeat(fishing.skillRight)} 🐟`,'skill-scale-cue'));choice([ui('왼쪽','Left'),ui('오른쪽','Right')],(value,index)=>index===fishing.skillTarget?nextSkillRound():skillFail())
