  function difficultyRule(){return difficultyRules[activeDifficulty()]||difficultyRules.medium}
  function difficultyCopy(id=selectedDifficulty){return {easy:ui('쉬움 · 미끼 무제한 · 물고기 자주','EASY · Endless bait · fish often'),medium:ui('보통 · 보통 속도 · 코인 보통','MEDIUM · Balanced · medium coins'),hard:ui('어려움 · 빠르게! · 코인 많이','HARD · Fast! · more coins')}[id]}
