  enterHarbor.onclick=openDifficultySetup;
  function chooseCoinReward(){const rule=difficultyRule(),weights=rule.coinWeights,total=weights.reduce((sum,value)=>sum+value,0);let roll=Math.random()*total,index=weights.findIndex(weight=>(roll-=weight)<=0);if(index<0)index=0;return {...coinRewards[index],amount:rule.coinValues[index],weight:weights[index]}}
  function skillDifficulty(fish){const score=fish?.score||100,rule=difficultyRule();let base;if(score>=1200)base={tier:'legend',goal:5,time:7600};else if(score>=600)base={tier:'hard',goal:4,time:8800};else if(score>=250)base={tier:'medium',goal:3,time:9900};else base={tier:'easy',goal:2,time:10800};return{...base,goal:Math.max(1,base.goal+rule.skillGoal),time:Math.round(base.time*rule.skillTime)}}
